def _base_of(case):
    """Strip the endpoint path's segments off the URL: .../app/api/v1/x/{id} -> .../app"""
    segments = [s for s in case.path.split('/') if s]
    parsed = urlparse(case.url)
    url_segments = [s for s in parsed.path.split('/') if s]
    keep = url_segments[:len(url_segments) - len(segments)] if len(url_segments) >= len(segments) else []
    return f'{parsed.scheme}://{parsed.netloc}' + ''.join('/' + s for s in keep)


def _fingerprint(case, url):
    raw = json.dumps({'folder': case.folder.name, 'method': case.method, 'url': url,
                      'content_type': case.content_type, 'headers': case.headers,
                      'query_params': case.query_params, 'body': case.body}, sort_keys=True)
    return hashlib.sha256(raw.encode()).hexdigest()


def move_existing_apis_into_default_environment(apps, schema_editor):
    Environment = apps.get_model('apitesting', 'Environment')
    ApiFolder = apps.get_model('apitesting', 'ApiFolder')
    ApiTestCase = apps.get_model('apitesting', 'ApiTestCase')
    CollectionSource = apps.get_model('apitesting', 'CollectionSource')
    ImportSession = apps.get_model('apitesting', 'ImportSession')
    project_ids = (set(ApiFolder.objects.values_list('project_id', flat=True))
                   | set(CollectionSource.objects.values_list('project_id', flat=True)))
    for project_id in project_ids:
        cases = list(ApiTestCase.objects.filter(project_id=project_id).select_related('folder'))
        bases = Counter(_base_of(c) for c in cases if c.url.startswith('http'))
        base = bases.most_common(1)[0][0] if bases else 'https://example.com'
        env = Environment.objects.create(project_id=project_id, name='Default', base_url=base)
        ApiFolder.objects.filter(project_id=project_id).update(environment=env)
        CollectionSource.objects.filter(project_id=project_id).update(environment=env)
        ImportSession.objects.filter(project_id=project_id).delete()
        for case in cases:
            if case.url == base or case.url.startswith(base + '/'):
                case.url = '{{baseUrl}}' + case.url[len(base):]
            case.environment = env
            # keep imported (non-manual) cases matching on the next sync
            if case.fingerprint:
                case.fingerprint = _fingerprint(case, case.url)
            case.save()


